<?php defined('BASEPATH') or exit('No direct script access allowed');$values=$values??[];$field=$field??'new'; ?>
<label for="<?= $esc($field); ?>-description">Descrição</label><input id="<?= $esc($field); ?>-description" class="form-control" name="expense[description]" maxlength="191" value="<?= $esc($values['description']??''); ?>" required>
<label for="<?= $esc($field); ?>-category">Categoria desta empresa</label><select id="<?= $esc($field); ?>-category" class="form-control" name="expense[category_id]" required><option value="">Selecione</option><?php foreach($categories as $category){if(!(int)$category['active']&&(int)($values['category_id']??0)!==(int)$category['id'])continue;?><option value="<?= (int)$category['id']; ?>" <?= (int)($values['category_id']??0)===(int)$category['id']?'selected':''; ?>><?= $esc($category['name'].((int)$category['active']===0?' (arquivada; escolha outra)':'')); ?></option><?php } ?></select>
<label for="<?= $esc($field); ?>-client">Cliente autorizado (opcional)</label><select id="<?= $esc($field); ?>-client" class="form-control" name="expense[client_id]"><option value="0">Sem vínculo</option><?php if((int)($values['client_id']??0)!==0&&!in_array((int)$values['client_id'],array_map(static fn($r)=>(int)$r['userid'],$clients),true)){?><option selected value="<?= (int)$values['client_id']; ?>">Referência anterior indisponível: remova ou selecione cliente autorizado</option><?php } ?><?php foreach($clients as $client){?><option value="<?= (int)$client['userid']; ?>" <?= (int)($values['client_id']??0)===(int)$client['userid']?'selected':''; ?>><?= $esc($client['company']); ?></option><?php } ?></select>
<label for="<?= $esc($field); ?>-project">Projeto ativo do cliente selecionado (opcional)</label><select id="<?= $esc($field); ?>-project" class="form-control" name="expense[project_id]"><option value="0">Sem vínculo</option><?php if((int)($values['project_id']??0)!==0&&!in_array((int)$values['project_id'],array_map(static fn($r)=>(int)$r['id'],$projects),true)){?><option selected value="<?= (int)$values['project_id']; ?>">Referência anterior indisponível: remova ou selecione projeto ativo autorizado</option><?php } ?><?php foreach($projects as $project){?><option value="<?= (int)$project['id']; ?>" <?= (int)($values['project_id']??0)===(int)$project['id']?'selected':''; ?>><?= $esc($project['name']); ?></option><?php } ?></select>
<label for="<?= $esc($field); ?>-date">Data da despesa</label><input id="<?= $esc($field); ?>-date" type="date" class="form-control" name="expense[date]" value="<?= $esc($values['expense_date']??date('Y-m-d')); ?>" required>
<?php if($values){ ?><input type="hidden" name="expense[currency]" value="<?= $esc($values['currency']); ?>"><p>Moeda preservada: <?= $esc($values['currency']); ?></p><?php }else{ ?>
<label for="<?= $esc($field); ?>-currency">Moeda</label><select id="<?= $esc($field); ?>-currency" class="form-control" name="expense[currency]"><option>BRL</option><option>USD</option><option>EUR</option></select><?php } ?>
<label for="<?= $esc($field); ?>-amount">Valor base (decimal com ponto)</label><input id="<?= $esc($field); ?>-amount" class="form-control" inputmode="decimal" name="expense[amount]" pattern="[0-9]+(\.[0-9]{1,2})?" value="<?= $values?$esc(CompanyExpenses::money((int)$values['amount_cents'])):''; ?>" required>
<label for="<?= $esc($field); ?>-tax">Tributo adicional (%)</label><input id="<?= $esc($field); ?>-tax" class="form-control" inputmode="decimal" name="expense[tax_rate]" pattern="[0-9]+(\.[0-9]{1,2})?" value="<?= $esc(CompanyExpenses::money((int)($values['tax_rate']??0))); ?>" required><p>O tributo informado é somado ao valor base. Não representa retenção, escrituração fiscal ou quitação bancária.</p>
<label for="<?= $esc($field); ?>-note">Observação</label><textarea id="<?= $esc($field); ?>-note" class="form-control" name="expense[note]" maxlength="4000"><?= $esc($values['note']??''); ?></textarea>
